create table public.fee_structures(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id),class_id uuid references public.classes(id),name text not null,amount numeric(12,2) not null check(amount>=0),frequency text not null default 'monthly',due_day smallint check(due_day between 1 and 31),active boolean not null default true,created_at timestamptz not null default now());
create table public.student_fee_assignments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id),fee_structure_id uuid not null references public.fee_structures(id),discount_amount numeric(12,2) not null default 0 check(discount_amount>=0),notes text,created_at timestamptz not null default now(),unique(student_id,fee_structure_id));
create table public.fee_payments(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,student_id uuid not null references public.students(id),fee_structure_id uuid references public.fee_structures(id),amount numeric(12,2) not null check(amount>0),payment_date date not null default current_date,payment_method text not null default 'cash',reference_no text,receipt_no text not null,notes text,collected_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(school_id,receipt_no));
alter table public.fee_structures enable row level security;alter table public.student_fee_assignments enable row level security;alter table public.fee_payments enable row level security;
create policy "read fee structures" on public.fee_structures for select using(public.is_school_member(school_id));create policy "manage fee structures" on public.fee_structures for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read fee assignments" on public.student_fee_assignments for select using(public.is_school_member(school_id));create policy "manage fee assignments" on public.student_fee_assignments for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read payments" on public.fee_payments for select using(public.is_school_member(school_id));create policy "manage payments" on public.fee_payments for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));